import { expect, sample, test, uniqueName } from "../../fixtures";
import type { APIRequestContext } from "@playwright/test";

const TAG = "@REV-03";

type Doc = { id: string; status: string };

async function waitForExtraction(member: APIRequestContext, documentId: string): Promise<void> {
  const deadline = Date.now() + 60_000;
  while (Date.now() < deadline) {
    const response = await member.get(`/api/documents/${documentId}`);
    expect(response.status()).toBe(200);
    const doc = (await response.json()) as Doc;
    if (doc.status !== "processing") {
      expect(doc.status).toBe("extracted");
      return;
    }
    await new Promise((resolve) => setTimeout(resolve, 1_000));
  }
  throw new Error(`document ${documentId} was still processing after 60s`);
}

async function uploadDocument(
  member: APIRequestContext,
  vendorId: string,
  kind: "w9" | "insurance_certificate" | "contract",
  body: string,
): Promise<string> {
  const response = await member.post(`/api/vendors/${vendorId}/documents`, {
    multipart: {
      kind,
      file: {
        name: `${kind}.pdf`,
        mimeType: "application/pdf",
        buffer: Buffer.from(body),
      },
    },
  });
  expect(response.status()).toBe(201);
  return ((await response.json()) as Doc).id;
}

/**
 * Creates a vendor with all three documents extracted and submits it,
 * leaving it in review. `insuranceBody` controls the insurance certificate
 * content; the unparsed-expiry vendor uses content whose expiry date cannot be parsed.
 */
async function createVendorInReview(
  member: APIRequestContext,
  name: string,
  insuranceBody: string,
): Promise<string> {
  const created = await member.post("/api/vendors", {
    data: { name, category: "services", contact_email: "ops@vendor.test" },
  });
  expect(created.status()).toBe(201);
  const vendorId = ((await created.json()) as { id: string }).id;

  const documentIds = [
    await uploadDocument(member, vendorId, "w9", "W-9 form content"),
    await uploadDocument(member, vendorId, "insurance_certificate", insuranceBody),
    await uploadDocument(member, vendorId, "contract", "Master services contract"),
  ];
  for (const id of documentIds) {
    await waitForExtraction(member, id);
  }

  const submitted = await member.post(`/api/vendors/${vendorId}/submit`);
  expect(submitted.status()).toBe(200);
  expect((await submitted.json()).status).toBe("in_review");
  return vendorId;
}

test.describe("review queue ordering", () => {
  test(
    "vendor with an unparsed insurance expiry is listed first, queue sorted by lowest confidence",
    { tag: TAG },
    async ({ apiAs }) => {
      // Arrange
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");

      const unparsedName = uniqueName("Review Unparsed");
      const otherName = uniqueName("Review Parsed");

      const unparsedId = await createVendorInReview(
        member,
        unparsedName,
        "Insurance certificate. Expiry: not-a-date",
      );
      const otherId = await createVendorInReview(
        member,
        otherName,
        "Insurance certificate. Expiry: 2030-01-31",
      );

      // Act
      const response = await reviewer.get("/api/review-queue");

      // Assert
      expect(response.status()).toBe(200);
      const queue = (await response.json()) as Array<{
        vendor_id: string;
        vendor_name: string;
        lowest_confidence: number;
      }>;

      const unparsedIndex = queue.findIndex((item) => item.vendor_id === unparsedId);
      const otherIndex = queue.findIndex((item) => item.vendor_id === otherId);
      expect(unparsedIndex, "unparsed-date vendor should be in the queue").toBeGreaterThanOrEqual(0);
      expect(otherIndex, "other vendor should be in the queue").toBeGreaterThanOrEqual(0);
      expect(unparsedIndex).toBeLessThan(otherIndex);

      expect(queue[unparsedIndex].lowest_confidence).toBeLessThanOrEqual(
        queue[otherIndex].lowest_confidence,
      );

      for (let i = 1; i < queue.length; i++) {
        expect(
          queue[i].lowest_confidence,
          `queue item ${i} should not have lower confidence than item ${i - 1}`,
        ).toBeGreaterThanOrEqual(queue[i - 1].lowest_confidence);
      }
    },
  );
});
